pub fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();
    assert_eq!(vals_2.len(), n, "vals_2 must have the same length as vals_1");
    assert_eq!(conds_1.len(), n, "conds_1 must have the same length as vals_1");
    assert_eq!(conds_2.len(), n, "conds_2 must have the same length as vals_1");
    assert_eq!(avgs.len(), n, "avgs must have the same length as vals_1");

    for i in 0..n {
        let a = vals_1[i];
        let b = vals_2[i];
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        avgs[i] = if c1 && c2 {
            // both true → integer average
            (a + b) / 2
        } else if c1 {
            // only first true
            a
        } else {
            // only second true (we know at least one is true)
            b
        };
    }
}

